const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([-50.925784, 46.694935]);
  const point2 = ee.Geometry.Point([-58.528990, 46.809436]);
  const date = '2019-09-19';

  // 2. Data Acquisition - Sentinel-2 Surface Reflectance
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(ee.Geometry.MultiPoint([point1, point2]));

  const s2Size = s2.size().getInfo();
  console.log(`Sentinel-2 Images: ${s2Size}`);

  if (s2Size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get image and mask clouds
  const image = s2.first();

  // Cloud masking using QA60 band
  const qa = image.select('QA60');
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
    .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
  const maskedImage = image.updateMask(mask);

  // 4. Calculate water color index (using blue band reflectance for milky water)
  // Milky water typically has higher reflectance in blue/green bands
  const blueBand = maskedImage.select('B2'); // Blue band

  // 5. Extract values at both points
  const extractValue = function(point) {
    return blueBand.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: point,
      scale: 1000,
      maxPixels: 1e9
    }).get('B2');
  };

  const val1 = extractValue(point1).getInfo();
  const val2 = extractValue(point2).getInfo();

  // Check for valid pixels
  const count1 = blueBand.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point1.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).get('B2').getInfo();

  const count2 = blueBand.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point2.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).get('B2').getInfo();

  console.log(`Point1 Blue Reflectance: ${val1}, Valid Pixels: ${count1}`);
  console.log(`Point2 Blue Reflectance: ${val2}, Valid Pixels: ${count2}`);

  // 6. Validation & Final Answer
  if (val1 === null || val2 === null || count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
  } else if (isNaN(val1) || isNaN(val2) || val1 === undefined || val2 === undefined) {
    console.log("<answer>C3</answer>");
  } else {
    // Higher blue reflectance indicates more milky water
    if (val1 > val2) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
